SELECT s1."c0" AS "x" FROM (SELECT s2."c0" AS "c0", s2."o" AS "o" FROM (SELECT s5."c0" AS "c0", ROW_NUMBER() OVER (ORDER BY s5."b" ASC NULLS LAST, s5."o" ASC NULLS LAST) AS "o" FROM ((SELECT s3."c0" AS "c0", s3."o" AS "o", 0 AS "b" FROM (SELECT v."c0" AS "c0", v."o" AS "o" FROM (VALUES (1, 0), (2, 1)) AS v("c0", "o")) AS s3) UNION ALL (SELECT s4."c0" AS "c0", s4."o" AS "o", 1 AS "b" FROM (SELECT v."c0" AS "c0", v."o" AS "o" FROM (VALUES (3, 0), (4, 1)) AS v("c0", "o")) AS s4)) AS s5) AS s2 ORDER BY s2."o" ASC NULLS LAST LIMIT 2 OFFSET 1) AS s1 ORDER BY s1."o" ASC NULLS LAST
